INSERT INTO channels (id, name, url, tier, tag, blurb, featured, n, category_id) VALUES
(0, 'Applied Science', 'https://www.youtube.com/channel/UCivA7_KLKWo43tFcCkFvydw', 'S', 'S in 2020 too', 'Ben Krasnow’s channel Applied Science has been the flagship channel of engineering and science YouTube for many years. In every video he explains some new and interesting piece of science and engineering he’s replicated in his shop. He’s made aerogel, a water jet cutter, a plasma sputtering chamber, an EDM drill, air bearings, an electroluminescent display, an LCD, and the source of his earliest publicity: a scanning electron microscope. He’s a truly prolific and incredible engineer who works with all kinds of electronics, machining, chemistry, physics and software. Every video leaves me in awe of him. Often he’ll be the first non-professional to try recreating something based on a procedure from papers and have to do dozens of failed experiments before making a video documenting the process and all the extra considerations. His videos and skill are incredible and I’ve learned a lot about the process of scientific lab work from watching them.', 'NwhVJ7cv9B4', 278, 1),
(1, 'Clickspring', 'https://www.youtube.com/channel/UCworsKCR-Sx6R6-BnIjS2MA', 'S', 'S in 2020 too', 'Clickspring is a channel about clockmaking, and watching it is wireheading on pure craftsmanship. I’ve never done any machining and don’t plan on ever making a clock, but his videos along with everything he makes in them are gorgeous examples of making everything with care and a commitment to excellence. This shows through in everything he does, from making custom screws with stunning blue oxide finish and hand-rounded interior ends that aren’t even visible when assembled to doing original research and building some authentic ancient tools for his reconstruction of the Antikythera mechanism. He puts the same care into his videos as the work itself: the camera shots and lighting are beautiful, the machining operations are seamlessly sped up at the right times to fit in the video but show the key moments, and he often includes nice composited overlays of the CAD model on top of the raw stock so you can understand what he’s doing, and the narration, music and sounds of the machining are excellently done to give the videos a relaxing feel. Every Clickspring video is just a delightful experience to watch. He also does videos without narration that just beatifully show all the machining and other work that goes into making something, this video being the most impressive example. He has a second channel called Clickspring Clips where he posts 2-4 minute non-narrated videos showing the making of one interesting part of his larger projects. His Patreon also has many exclusive videos once you watch all the public ones.', 'XsmGHMic8vs', 133, 3),
(2, 'Stuff Made Here', 'https://www.youtube.com/channel/UCj1VqrHhDte54oLgPG4xpuQ', 'S', 'S in 2020 too', 'Stuff Made Here is the newest channel to enter S tier. When YouTube first recommended one of his videos to me 4 months ago the channel had just started with a few videos and I thought “huh how is this brand new channel getting hundreds of thousands of views”, then I watched the video and thought “okay wow, apparently if you make really excellent stuff from the start it can become popular on YouTube super fast”. He just makes really interesting and impressive videos where he uses his skill in many different disciplines of engineering to make cool stuff and then gives interesting descriptions of all the considerations, testing, engineering, fabrication and failures that went into making it. For his most popular video he makes a basketball backboard that always directs the ball into the hoop. He designs and builds a custom mechanism to move the backboard to any distance and angle using rods that minimize the weight on the board so it can move quickly, describing the kinematic principles and how he constructed it using CNC plasma cut and spot welded sheet metal with 3D printed joints. Then he describes the clever custom algorithm for filtering out the basketball from other moving objects in the depth camera by fitting a ballistic curve to all possible object trajectories, as well as the software for extrapolating and calculating the required backboard position. The way he did everything is quite impressive and, like all his projects, he did it in only a few weeks while also having a day job. What sets him apart from other YouTube makers is not only the skill in so many different areas that his projects display, but also the detailed explanations of the entire engineering process including the considerations, math, algorithms and failures rather than just the fabrication. If this sounds good to you, you should watch every single one of his videos including the ones that might not look that interesting. There’s not that many yet, but there might be soon since he somehow has also been managing to post more frequently than anyone else in my S tier (have I mentioned he also has a day job!?).', 'RpslsMqPFWA', 42, 2),
(3, 'Captain Disillusion', 'https://www.youtube.com/channel/UCEOXxzW2vU0P-0THehuIIeg', 'S', 'S in 2020 too', 'Captain Disillusion has been on YouTube for 12 years now, originally in obscurity but gradually growing to millions of viewers. He goes over trick and hoax viral videos and explains the visual effects used to make them. The thing that’s incredible is the production value: Costumes, makeup, well-written scripts, and a ridiculous density of impressive visual effects. Captain Disillusion is what happens when an incredibly talented and driven visual effects artist puts an entire month of full time work into every single 5 minute video. He’s done streams and time-lapses before of him spending dozens of hours on a 3 second visual effect for a throwaway gag. A typical video consists of a well-written and edited intro of him introducing a faked video, doing a detailed breakdown of all the components of the effect but quickly thanks to amazing visual aid footage, then him just one-upping the original video by doing the effect so much better than anyone else has ever done it, without the tells he went over. Here’s some other, good ones but really every single one is excellent.', '2yCjO-wRxyM', 112, 13),
(4, 'Kiwami Japan', 'https://www.youtube.com/channel/UCg3qsVzHeUt5_cPpcRtoaJQ', 'S', 'S in 2020 too', 'This is a weird and wonderful channel that to me really exemplifies what’s great about YouTube. Most videos are of the form “sharpest X kitchen knife in the world” with a thumbnail of a hand holding a weird knife in the same pose. Some examples of X are “Fungi”, “Paper”, “milk”, “Pasta”, “Underwear”, and “smoke”. I originally ignored suggested videos from this channel because I assumed they were some weird click-bait that didn’t really make a knife from those materials, and that was tragic because he really does and it’s amazing. Every video has no talking or words except for occasional subtitles, and follows the process starting from the raw material, demonstrating all the processing steps required to make a hard substance out of it, casting a knife blank, sharpening it, and testing it. At some point early in the channel’s history someone must have commented that the videos were like ASMR videos because after that he got a high quality microphone and puts a lot of emphasis on the sounds. The coolest part is he’s clearly really good at materials science and every video has amazing steps all done in his apartment. Lets take the “sharpest Seawater kitchen knife in the world” video as an example: It starts with a shot of him getting huge jugs of seawater from the ocean and collecting shells on the beach. At home he boils the seawater into salt and a solution he labels “magnesium chloride”. Then he puts a seashell on top of a charcoal briquette and puts it in an insulating firebrick box in his home microwave-oven-thing and cuts to it coming out totally calcified (apparently you can do that without a furnace??). He grinds it up with the subtitle “quicklime”, puts it in water and uses a thermal camera to show the exothermic reaction to get slaked lime. Cut to him combining a concentrated sea brine with the lime water to get “magnesium hydroxide + salt”. He adds water to dissolve the salt and filters out the magnesium hydroxide, combines it with the magnesium chloride from earlier, dries it, uses his handy durometer to show it fails a hardness test. He pops the magnesium hydroxide in his charcoal microwave furnace to get “magnesium oxide” and shows that this time when combined and dried it yields a very hard rock-like substance. Cut to him pouring a bunch of it in a rectangular plastic box, drying it and sawing out a knife shape. Then his famous sharpening sequence with increasingly fine knife stones, followed by the ever-present cucumber chopping test (complete with weird cucumber reveal out of godzilla-themed rubber gloves). He finishes by showing that the “magnesium cement” (Wiki link) doesn’t immediately dissolve in watera and that it can also be combined with dirt to make bricks. I can’t see anything remotely like this every being green-lit as a TV series, but every video is brilliant and relaxing, they all get millions of views with zero advertising spend, because everyone likes them and recommends them to friends and algorithmic recommendations respond to that in a way that human TV producers wouldn’t have the guts to. People complain about the “YouTube algorithm”, but at this kind of thing it truly shines.', 'pFG-nXUw6Ts', 75, 3),
(5, 'Steve Mould', 'https://www.youtube.com/channel/UCEIwxahdLz7bap-VDs9h35A', 'A', 'A in 2020 too', 'Interesting science concept explanation videos with demonstrations. I was waffling between A and B tier but this phenomenally cool recent video on optical rotation blew me away and secured his spot in A tier.', '6gsZY_-kT3U', 241, 1),
(6, 'S3 | Science, Startups, & Stories', 'https://www.youtube.com/channel/UC0-7PyfpOIJpNyi8WrHiyXA', 'A', 'new', 'Really well produced videos about interesting startups building cool things, great curation.', 'qNBEqnFt1aU', 123, 5),
(7, 'Primitive Technology', 'https://www.youtube.com/channel/UCAL3JXZSzSm8AlZyD3nQdBA', 'A', 'A in 2020 too', 'Guy goes out into the woods in Australia and makes pottery, metal, shelter, tools and materials starting with no tools at all. This video about making a kiln to smelt iron is really good.', 'PXuV_YCt8g4', 107, 12),
(8, 'Know Art', 'https://www.youtube.com/channel/UCQnMw9GGDS3xO6fN5oae-4w', 'A', 'new', 'Well animated videos explaining interesting mechanisms, with interesting explanations and choice of topics', 'bp2IAlU53uw', 85, 2),
(9, 'Breaking Taps', 'https://www.youtube.com/channel/UC06HVrkOL33D5lLnCPjr6NQ', 'A', 'D in 2020', 'Really interesting projects mixing science, hardware and software. Kind of like Applied Science, which is a big compliment.', 'GbcN0bPs-Ig', 82, 1),
(10, 'NileRed', 'https://www.youtube.com/channel/UCFhXFikryT4aFcLkLw2LBLA', 'A', 'A in 2020 too', 'Famously excellent chemistry channel, tries to synthesize cool things like alcohol from air and chronicles the failures along the way', 'ID-K64Jk6JM', 254, 1),
(11, 'Huygens Optics', 'https://www.youtube.com/channel/UC26YLK0OEbLB3TCYxGh8xVQ', 'A', 'new', 'Combination of animated wave physics explainers of optical phenomena, and hands-on videos about building optical equipment and fabricating lenses. Got me interested in optics.', 'TPyQI7bJo6Q', 64, 1),
(12, 'AlphaPhoenix', 'https://www.youtube.com/channel/UCCWeRTgd79JL0ilH0ZywSJA', 'A', 'new', 'Makes his own experimental apparatus to demonstrate interesting scientific concepts and effects and explains them really well. For example taking “video” of a laser propagating through a room.', 'o4TdHrMi6do', 116, 1),
(13, 'NightHawkInLight', 'https://www.youtube.com/channel/UCFtc3XdXgLFwhlDajMGK69w', 'A', 'A in 2020 too', 'Does original experiments on how to bring different cutting edge science into a home-accessible form. I’ve learned about a lot of really cool things from this channel, like novel cheap ion-exchange membranes for metal refining, and materials that achieve colder than ambient temperatures by radiating away heat in parts of the spectrum where the atmosphere is more transparent.', 'z4_GxPHwqkA', 352, 1),
(14, 'Animagraffs', 'https://www.youtube.com/channel/UCnZeeKO8qVdtkrA4-uKhtTw', 'A', 'new', 'Spends ages making detailed 3D models of various interesting things like galleons, the hoover damn and airplanes, then makes hour long videos explaining every detail of how the thing works. Long but extremely worth it.', 'tBN2o4rAt5A', 37, 2),
(15, 'Works By Design', 'https://www.youtube.com/channel/UC0G7e3uCtTyKQy2vZbRaKxg', 'A', 'new', 'Attempts challenging projects like a pickproof lock, and makes really excellent videos explaining the engineering process, with great animations. Kinda like Stuff Made Here, which is a big compliment.', '-qUu8kIliy8', 15, 2),
(16, 'suckerpinch', 'https://www.youtube.com/channel/UC3azLjQuz9s5qk76KEXaTvA', 'A', 'B in 2020', 'The best computer science elaborate joke videos. Super impressive programming projects done in the name of elaborate performance comedic art.', 'M1si1y5lvkk', 40, 5),
(17, 'Joshua Bird', 'https://www.youtube.com/channel/UCDyZXmOevDAb6DHyUCwzVNg', 'A', 'new', 'College student who’s only done a few videos but all of them are great. He has exactly my project aesthetic: mechanical+software projects where he combines a bit of mechanical novelty with a bunch of software cleverness in order to get something simple to achieve great results.', 'Ndftcft6XhU', 9, 2),
(18, 'Dan Gelbart', 'https://www.youtube.com/channel/UCYA1VjSKXgNVh03wjw_HSRA', 'A', 'A in 2020 too', 'Dan is an incredible engineer who made a fortune selling companies and now has an amazing machine shop, with lots of tools he’s built or modified himself. He doesn’t post videos very often but the main draw of his channel is the 7 year old 19-part series on tools and techniques for building prototypes. It’s a masterpiece of incredible knowledge, impressive designs and great tips. I recently rewatched the whole series.', 'OuZjjActWmQ', 27, 2),
(19, 'Practical Engineering', 'https://www.youtube.com/channel/UCMOqf8ab-42UUQIdVoKwjlQ', 'B', 'A in 2020', 'Explains interesting things from civil engineering often with cool models and demonstrations. I found this one on hydraulic ram pumps really cool.', 'Ku_ockR2t44', 236, 2),
(20, 'Real Engineering', 'https://www.youtube.com/channel/UCR1IuLEqb6UEA_zQ81kwXfg', 'B', 'B in 2020 too', 'Well-produced and interesting explanation videos on various engineering topics. From the engineering of fighter planes to flood control systems in The Netherlands.', 'iGZsPFJuxc0', 209, 2),
(21, 'Historia Civilis', 'https://www.youtube.com/channel/UCv_vLHiWVBh_FR9vbeuiY-A', 'B', 'new', 'Excellent animated historical video series on Roman history.', 'R0wwuj0sTyY', 89, 6),
(22, 'BPS.space', 'https://www.youtube.com/channel/UCILl8ozWuxnFYXIe2svjHhg', 'B', 'D in 2020', 'Very fancy model rockets with cool control systems, like Falcon propulsive landing.', 'G61T-5d9jiA', 211, 4),
(23, 'The Thought Emporium', 'https://www.youtube.com/channel/UCV5vCi3jPJdURZwAOO_FNfQ', 'B', 'A in 2020', 'Very wide-ranging science channel. Often has interesting biology experiments. Not as consistently great but has some top hits like doing his own DIY gene therapy for lactose intolerance.', '1sgsb-F8dCw', 107, 1),
(24, 'TierZoo', 'https://www.youtube.com/channel/UCHsRtomD4twRf5WVHHk-cMw', 'B', 'B in 2020 too', 'A biologist explains interesting animal facts as funny parodies of video game commentary and tier lists (I am partial to the tier list format as evidenced by this very tier list). This one on turtles is pretty good.', 'xtnfcm-fxm4', 103, 1),
(25, 'Excessive Overkill', 'https://www.youtube.com/channel/UCwbyKKmjVdCpWzZZY-WnajA', 'B', 'new', 'Mechatronics projects with very impressive engineering like custom FPGA reverse engineered industrial robot controllers and auto-aim airsoft gun.', 'gqVJDHK5EjM', 34, 2),
(26, 'Tech Ingredients', 'https://www.youtube.com/channel/UCVSHXNNBitaPd5lYz48--yg', 'B', 'A in 2020', 'Long and detailed technical videos of interesting projects demonstrating cool science and engineering concepts. They build really high quality demonstration pieces for each video and lots of the concepts they look into are little known ones like magnetohydrodynamics, how helium is an incredibly good sound suppressor and plasma physics. The main presenter is super knowledgeable and every video has some really interesting things. It’s a bit slow paced but I fix that by always watching on 2x speed. They also just posted a Best Of clips compilation video.', 'G1Syjh319VU', 184, 1),
(27, 'USCSB', 'https://www.youtube.com/channel/UCXIkr0SRTnZO4_QpZozvCCA', 'B', 'new', 'Animated videos of industrial disasters. These are way better than they sound. They teach you a lot both about how things can go wrong even in industries that try hard on safety, and in each video you learn about a sample of American industry and what work is like there.', 'HmiQFYGc6C4', 106, 2),
(28, 'Tom Stanton', 'https://www.youtube.com/channel/UC67gfx2Fg7K2NSHqoENVgwA', 'B', 'B in 2020 too', 'Implements really creative and cool engineering ideas mostly using a lot of 3D printing. Some of his coolest videos are building drones using weird things like gas thrusters, reaction wheels, the Coanda effect and a single rotor with no swashplate.', 'Co57SfcT-h0', 150, 2),
(29, 'Sam Zeloof', 'https://www.youtube.com/channel/UC7E8-0Ou69hwScPW1_fQApA', 'B', 'B in 2020 too', 'One of the only people to successfully produce a silicon integrated circuit at home, and when he was in high school. This year he started putting out high-effort videos on cool equipment used in the process.', 'mvZ1dJuvenw', 35, 5),
(30, 'Demoscene High-Quality Videos', 'https://www.youtube.com/channel/UC96JVq-z0-0iHAkIkKp1_6w', 'B', 'B in 2020 too', '64k intros, where people write programs that produce beautiful visuals and audio using an executable less than 64 kilobytes, are perhaps my favorite art form accross all art forms. They often use very non-standard rendering techniques that lead to unique visuals, have good electronic background tracks, and the whole time I marvel at the technical wizardry of the tiny size. Not all the best videos are on this channel and not all the ones on this channel are good but it has many good ones. My favorite intro group is Logicoma, even before I found out they use Rust. My favorites of their stuff: Engage, Dope On Wax, Trash Panda and Elysian. Favorites by other groups include on, Zetsubo (4k!), delight, Offscreen Colonies and the timeless.', NULL, 888, 5),
(31, 'Engineering Explained', 'https://www.youtube.com/channel/UClqhvGmHcvWL9w3R48t9QXQ', 'C', 'new', 'This channel got me interested in cars and engines, which I wasn’t before. It explains things like valve timing and how high end cars work from an engineering perspective on a whiteboard.', '0mU7p4_CbBA', 1002, 8),
(32, 'SuperfastMatt', 'https://www.youtube.com/channel/UCU5adS8d-YX7GbJcnH0x6uA', 'C', 'new', 'Fun custom car projects, shows different interesting making techniques.', 'IGyUNd7Ax0Y', 196, 8),
(33, 'The Operations Room', 'https://www.youtube.com/channel/UCnZJt7yQw5IztVwe-Dscd-Q', 'C', 'new', 'Animated major battles, especially naval. Interesting to learn the history.', 'cxh4II6zN4s', 181, 6),
(34, 'Tom Scott', 'https://www.youtube.com/channel/UCBa659QWEk1AI4Tg--mrJ2A', 'C', 'B in 2020', 'Popular channel mostly focusing on talking about random interesting places with neat stories around the world.', 'TumxO2glmPQ', 764, 6),
(35, 'Hyperspace Pirate', 'https://www.youtube.com/channel/UC8i-4EpLBXMzekETNXwcZjA', 'C', 'new', 'Funny guy makes various cryogenic refrigerators and chemical synthesis chains in his garage. I learned a lot about refrigeration cycles. Cool how much he can do with janky components.', 'UXNcivV8JNw', 100, 1),
(36, 'Munro Live', 'https://www.youtube.com/channel/UCj--iMtToRO_cGG_fpmP5XQ', 'C', 'new', 'Teardowns of cars and robots, explaining the manufacturing and cost tradeoffs involved in them.', 'CSJydnLzBAo', 832, 8),
(37, 'BuildWitt', 'https://www.youtube.com/channel/UCKqKiBDpq9j29bXbBx0cfOw', 'C', 'new', 'Tours of mines and industrial sites, really cool to see the processes and giant machines.', 'ywB-KBzHqtI', 325, 2),
(38, 'cubicmetre', 'https://www.youtube.com/channel/UCsrxrOtjmWnH5FJhJnkTRBg', 'C', 'new', 'Crazy technical Minecraft designer of the Minecraft equivalent of rods from God. I love seeing how various weird game behaviors get reverse engineered and used for technology through careful science and engineering, it’s directly analogous to the physics->R&D->engineering pipeline for real world technology.', 'm7Icley8A_A', 122, 7),
(39, 'Map Men', 'https://www.youtube.com/channel/UCbbQalJ4OaC0oQ0AqRaOJ9g', 'C', 'new', 'Fun and interesting videos about geography.', 'hX21ctsGhNc', 103, 6),
(40, 'Hacksmith Industries', 'https://www.youtube.com/channel/UCjgpFI5dU-D1-kh9H1muoxQ', 'C', 'B in 2020', 'Skilled engineers with a substantial budget and machine shop try to make real life versions of gadgets from fiction. Their main audience is kids and non-technical people and it shows, but many of their videos have pretty cool engineering, and their build montages are neat.', 'qgTfVQaHW5A', 867, 2),
(41, 'The Action Lab', 'https://www.youtube.com/channel/UC1VLQPn9cYSqx8plbk9RxxQ', 'C', 'new', 'Interesting science demo videos, kinda like NightHawkInLight or Steve Mould but not quite as good.', 'G6pTelud5-E', 992, 1),
(42, 'Technology Connections', 'https://www.youtube.com/channel/UCy0tKL1T7wFoYcxCe0xjN6Q', 'C', 'B in 2020', 'Guy explains interesting bits of technological history and science behind everyday gadgets. Like this video on how rice cookers use some neat physics tricks.', 'JzClLWL-Eys', 235, 5),
(43, 'GeoWizard', 'https://www.youtube.com/channel/UCW5OrUZ4SeUYkUg1XqcjFYA', 'C', 'C in 2020 too', 'Guy who is really good at GeoGuessr, that is super knowledgeable about geography and all sorts of tricks to figure out where you are when plopped randomly on Street View. This guy is allegedly better but IMO less entertaining.', 'q6hSUH9FKdY', 642, 6),
(44, 'The Intel Report', 'https://www.youtube.com/channel/UC7Ay_bxnYWSS9ZDPpqAE1RQ', 'C', 'new', 'Military history analysis videos by the creators of the Operations Room channel.', 'vw63IoVD9mk', 60, 6),
(45, 'Not An Engineer', 'https://www.youtube.com/channel/UCXh9mHdcBD-3aGCiECZMP1Q', 'C', 'new', 'Australian guy makes funny videos about his home machine shop projects.', 'BMCxCuTc1MA', 20, 3),
(46, 'CSI Starbase', 'https://www.youtube.com/channel/UCy6Q9UCG7Wa-N7nht2BFrHA', 'C', 'new', 'Really interesting animated deep dives into what’s going on at Starbase TX and how parts of the Starship program work. Including going into failures and how they’re manufacturing things.', 'Cu16K_AMuaY', 62, 4),
(47, 'AngeTheGreat', 'https://www.youtube.com/channel/UCV0t1y4h_6-2SqEpXBXgwFQ', 'C', 'new', 'Videos about his realistic engine physics simulator that are really interesting.', 'sUdnJTC2w9I', 39, 5),
(48, '3Blue1Brown', 'https://www.youtube.com/channel/UCYO_jab_esuFRV4b17AJtAw', 'C', 'new', 'Very pretty animated math videos.', 'd_qvLDhkg00', 153, 1),
(49, 'Chronova Engineering', 'https://www.youtube.com/channel/UC6DhSUKasPbBLCSdPcGBxww', 'C', 'new', 'Beautiful machining videos for interesting small machines.', '0Gi5Z51KdUE', 41, 3),
(50, 'Prop Department', 'https://www.youtube.com/channel/UCU0wOR4RQA9L7ZBOeyQI20A', 'C', 'new', 'Large scale vehicle fabrication expert makes cool stuff.', 'ID062k6AqMw', 21, 8),
(51, 'Joel Creates', 'https://www.youtube.com/channel/UCHk0IYEDJxQGQ-nbd3yP_KA', 'C', 'new', 'Small fun engineering videos. A bit like Tom Stanton.', 'LDr5hlG1GBU', 71, 2),
(52, 'Contraption Collection', 'https://www.youtube.com/channel/UC66lPJ8u2N1i2Bh_TMaWagg', 'C', 'new', 'Retired channel with an excellent machining series on making Balisong-style (flippy butterfly knife) scissors and all the challenges.', 'M88jllt4klM', 40, 3),
(53, 'Fireball Tool', 'https://www.youtube.com/channel/UCVveEFTOd6khhSXXnRhxJmg', 'C', 'new', 'Really interesting tool making and machining channel. Often kinda selling their own tools, but in a really interesting way with real tests.', '3AScojcf2Yw', 197, 3),
(54, 'Lafayette Systems', 'https://www.youtube.com/channel/UCDllNYyUN4fK1r-Nwffp7og', 'C', 'new', 'Amateur rocketry with active controls, kinda like BPS.space.', '8wmpQ9hiQ1g', 35, 4),
(55, 'Tucker Gott', 'https://www.youtube.com/channel/UCASjdyu0y8XQ9qJnqxsKHnQ', 'C', 'C in 2020 too', 'Paramotor pilot. I have no plans on ever paramotoring but it’s cool to watch and his “Reacting To Crash Videos” series is really interesting, seeing him break down what kind of safety considerations come into play and how things can go wrong.', 'Ui7DCKI_upA', 763, 11),
(56, 'This Old Tony', 'https://www.youtube.com/channel/UC5NO8MgTQKHAWXp6z8Xl7yQ', 'C', 'A in 2020', 'Really well-produced entertaining and funny machine shop and engine videos that usually use some small machining project to explain a concept or technique.', 'Ia3Iieejyg8', 234, 3),
(57, 'Deconstructed', 'https://www.youtube.com/channel/UCje6-Yak9u1msy5l7sE9pBA', 'C', 'new', 'Like Animagraffs in that they make interesting 3D model deconstruction videos, although not quite as cool ones', 'tCHk2ZteXEo', 34, 2),
(58, 'Current Concept', 'https://www.youtube.com/channel/UCW5i5rLbDiu9RhCEXj4BAZw', 'C', 'new', 'Very funny maker projects', 'tkO7tsHPu10', 36, 3),
(59, '2swap', 'https://www.youtube.com/channel/UCiNLr9wX35KksK77mrQgxiw', 'C', 'new', 'Like 3Blue1Brown: animated math explainers. Except I maybe find the average video even more beautiful and interesting, except there’s fewer videos.', 'kL9BTbIGxLg', 10, 1),
(60, 'Akiyuki Brick Channel', 'https://www.youtube.com/channel/UCCJJNQIhS15ypcHqDfEPNXg', 'C', 'C in 2020 too', 'Incredibly cool and complex Lego mechanical contraptions. This is a great combination of many of his designs and this recent video is aesthetically fun.', 'EG9ISMjM-uQ', 92, 3),
(61, 'SethBling', 'https://www.youtube.com/channel/UC8aG3LDTDwNR1UQhSn9uVrw', 'C', 'C in 2020 too', 'Does Super Mario World speedruns involving code injection via carefully placed shells and a glitch to warp directly to the credits, as well as various other technical video game trickery.', 'mq7T5_xH24M', 1081, 7),
(62, 'CNLohr', 'https://www.youtube.com/channel/UCG7yIWtVwcENg_ZS-nahg5g', 'C', 'B in 2020', 'Really interesting and cool electronics projects. Examples include reverse engineering the HTC Vive and making a custom Linux C SDK for it, running a custom Minecraft server on a microcontroller and pretty LEDs.', 'eIdHBDSQHyw', 207, 5),
(63, 'Pannen', 'https://www.youtube.com/channel/UC5miyvhPsWWyfTulnJ43koQ', 'C', 'C in 2020 too', 'Details various glitches used for an automated Super Mario 64 speedrun where he tries to minimize use of the A (jump) button. Really interesting just seeing how insane the tricks can be. Best and most famous video is this commentated one from his other channel about paralell universes.', 't14ENrqlmuY', 685, 7),
(64, 'Edison Motors', 'https://www.youtube.com/channel/UCUEzfzqf2fx3C1vs0MlgShA', 'D', 'new', 'Canadian loggers make an electric hybrid truck company', 'L1Yy-nsgBCM', 386, 8),
(65, 'NHRL', 'https://www.youtube.com/channel/UChgAZxOWR0S3Q376oAodGjQ', 'D', 'new', NULL, 'eVI9Ig3lq_o', 987, 13),
